```python
def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value or ""
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)
        value = value.strip().lower()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in ("gmail.com", "googlemail.com"):
                local = local.split("+", 1)[0].replace(".", "")
                value = f"{local}@gmail.com"

        if value.count("@") != 1:
            return ""
        local, domain = value.split("@")
        if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
            return ""
        return value

    def normalize_phone(value):
        value = value or ""
        marker = re.search(r"x|ext|#", value, flags=re.IGNORECASE)
        if marker:
            value = value[:marker.start()]
        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in "01":
            return ""
        return digits

    def normalize_zip(value):
        value = (value or "").strip()
        if "-" in value:
            value = value.split("-", 1)[0]
        if len(value) == 4 and value.isdigit():
            value = "0" + value
        return value if len(value) == 5 and value.isdigit() else ""

    def normalize_name(value):
        value = (value or "").strip()
        if value and (value.isupper() or value.islower()):
            value = value.title()
        return value

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    def opted_out(value):
        return (value or "").strip().lower() in {"y", "yes", "true", "1"}

    prepared = []
    for index, row in enumerate(rows):
        email = normalize_email(row.get("email", ""))
        phone = normalize_phone(row.get("phone", ""))
        if not email and not phone:
            continue

        source = (row.get("source") or "").strip().lower()
        prepared.append({
            "index": index,
            "row": row,
            "email": email,
            "phone": phone,
            "first_name": normalize_name(row.get("first_name", "")),
            "last_name": normalize_name(row.get("last_name", "")),
            "zip": normalize_zip(row.get("zip", "")),
            "source": source,
            "updated_dt": parse_updated(row["updated"]),
            "opted_out": opted_out(row.get("opted_out", "")),
        })

    # Union-find gives transitive person matching.
    parent = list(range(len(prepared)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    email_owner = {}
    phone_name_owner = {}

    for i, item in enumerate(prepared):
        if item["email"]:
            if item["email"] in email_owner:
                union(i, email_owner[item["email"]])
            else:
                email_owner[item["email"]] = i

        last_name_key = item["last_name"].casefold()
        if item["phone"] and last_name_key:
            key = (item["phone"], last_name_key)
            if key in phone_name_owner:
                union(i, phone_name_owner[key])
            else:
                phone_name_owner[key] = i

    groups = {}
    for i, item in enumerate(prepared):
        groups.setdefault(find(i), []).append(item)

    def pick(group, field, valid_only=False):
        candidates = [
            item for item in group
            if item[field] and (not valid_only or item[field])
        ]
        if not candidates:
            return ""
        # Manual source first, then newest updated, then earliest input row.
        chosen = min(
            candidates,
            key=lambda item: (
                item["source"] != "manual",
                -item["updated_dt"].timestamp(),
                item["index"],
            ),
        )
        return chosen[field]

    output = []
    for group in sorted(groups.values(), key=lambda g: min(item["index"] for item in g)):
        tags = set()
        for item in group:
            raw_tags = item["row"].get("tags", "") or ""
            for tag in re.split(r"[;,]", raw_tags):
                tag = tag.strip().lower()
                if tag:
                    tags.add(tag)

        latest = max(item["updated_dt"] for item in group)
        output.append({
            "first_name": pick(group, "first_name"),
            "last_name": pick(group, "last_name"),
            "zip": pick(group, "zip"),
            "email": pick(group, "email"),
            "phone": pick(group, "phone"),
            "source": pick(group, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(item["opted_out"] for item in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
